// Make available globally
if (typeof window !== 'undefined') {
  window.FIELDORA_TRANSLATIONS = i18nTranslations;
}

// Current active language state
let currentLanguage = typeof localStorage !== 'undefined' ? (localStorage.getItem('fieldora_lang') || 'en') : 'en';

function setLanguage(lang) {
  if (!i18nTranslations[lang]) lang = 'en';
  currentLanguage = lang;
  if (typeof localStorage !== 'undefined') {
    localStorage.setItem('fieldora_lang', lang);
  }
  
  applyCurrentLanguage();
  
  // Trigger dynamic re-renders across all active views
  if (typeof renderFarmerProduceGrid === 'function') renderFarmerProduceGrid();
  if (typeof renderBuyerProduceGrid === 'function') renderBuyerProduceGrid();
  if (typeof renderBuyerRfqs === 'function') renderBuyerRfqs();
  if (typeof renderFarmerDemands === 'function') renderFarmerDemands();
  if (typeof renderDemandIntelligence === 'function') renderDemandIntelligence();
  if (typeof updateDemandForecastView === 'function') updateDemandForecastView();
  if (typeof updateMilestoneUI === 'function') updateMilestoneUI();
  
  if (typeof loadOrderReviewState === 'function') {
    loadOrderReviewState('FD-1039', '8996d084-1f18-45bd-995a-27ac039436ce', 'fd-1039-review-container');
    loadOrderReviewState('FD-1038', '039b5a52-cfab-42df-9cbc-22214e210de5', 'fd-1038-review-container');
  }
}

function t(key, defaultText = '', params = {}) {
  const dict = i18nTranslations[currentLanguage] || i18nTranslations['en'];
  let text = dict[key] || (i18nTranslations['en'] && i18nTranslations['en'][key]) || defaultText || key;
  
  if (params && typeof params === 'object') {
    Object.keys(params).forEach(p => {
      text = text.replace(new RegExp('\\$\\{' + p + '\\}', 'g'), params[p]);
      text = text.replace(new RegExp('{' + p + '}', 'g'), params[p]);
    });
  }
  return text;
}

function translateStatus(status) {
  if (!status) return '';
  const s = String(status).toLowerCase();
  if (s.includes('active')) return t('status_active_marketplace', 'Active on Marketplace');
  if (s.includes('negotiat')) return t('status_under_negotiation', 'Under Negotiation');
  if (s.includes('confirmed')) return t('status_confirmed', 'Confirmed');
  if (s.includes('escrow') || s.includes('locked')) return t('status_escrow_locked', 'Escrow Locked');
  if (s.includes('transit')) return t('status_in_transit', 'In Transit');
  if (s.includes('delivered')) return t('status_delivered', 'Delivered');
  if (s.includes('completed')) return t('status_completed', 'Completed');
  if (s.includes('released')) return t('status_released', 'Released');
  return status;
}

function applyCurrentLanguage() {
  if (typeof document === 'undefined') return;
  
  // Update all [data-i18n] elements
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const key = el.getAttribute('data-i18n');
    const trans = t(key);
    if (trans) {
      if (el.tagName === 'INPUT' && (el.type === 'button' || el.type === 'submit')) {
        el.value = trans;
      } else {
        el.innerText = trans;
      }
    }
  });

  // Update HTML elements
  document.querySelectorAll('[data-i18n-html]').forEach(el => {
    const key = el.getAttribute('data-i18n-html');
    const trans = t(key);
    if (trans) {
      el.innerHTML = trans;
    }
  });

  // Update placeholders
  document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
    const key = el.getAttribute('data-i18n-placeholder');
    const trans = t(key);
    if (trans) {
      el.placeholder = trans;
    }
  });

  // Update language selector dropdown label if present
  const langDisplay = document.getElementById('active-lang-label') || document.getElementById('current-lang-label');
  if (langDisplay && i18nTranslations[currentLanguage]) {
    langDisplay.innerText = i18nTranslations[currentLanguage].label;
  }

  // Update checkmarks in dropdown
  const langCodes = ['en', 'hi', 'mr', 'gu', 'pa', 'te', 'ta', 'kn'];
  langCodes.forEach(code => {
    const chk = document.getElementById(`lang-chk-${code}`);
    if (chk) {
      if (code === currentLanguage) chk.classList.remove('hidden');
      else chk.classList.add('hidden');
    }
  });

  if (typeof closeLangMenu === 'function') {
    closeLangMenu();
  }

  // Preserve dynamic logged-in user profile if active
  if (typeof currentAuthUser !== 'undefined' && currentAuthUser && typeof updateUserUIElements === 'function') {
    updateUserUIElements(currentAuthUser);
  }
}

// Auto-initialize on DOMContentLoaded
if (typeof document !== 'undefined') {
  document.addEventListener('DOMContentLoaded', () => {
    applyCurrentLanguage();
  });
}
